//! Provider-neutral Health State repository backed by the existing Health Vault.
use std::cmp::Ordering;use thiserror::Error;use crate::canonical_authorization::AuthorizationRequest;use crate::local_health_vault::LocalHealthVaultRecord;use crate::local_health_vault_storage::{AuthorizationContext,LocalFileVaultStore,StorageError,VaultAuthorizer,VaultKeyProvider};
const HEALTH_STATE_CONTENT_TYPE:&str="application/json";const ALLOWED_ENTITY_TYPES:[&str;8]=["person","observation","interpretation","goal","context","intervention","response","outcome"];
#[derive(Debug,Clone,PartialEq,Eq)]pub struct AuthorizedHealthStateAccessContext{principal_ref:String,subject_ref:String,scope:String,capability_id:String,resource_type:String,resource_id:String,action:String}
impl AuthorizedHealthStateAccessContext{pub(crate)fn from_authorized_request(r:&AuthorizationRequest)->Result<Self,HealthStateRepositoryError>{let v=[&r.principal_ref,&r.subject_ref,&r.capability_id,&r.resource_type,&r.resource_id,&r.action,&r.tenant_id,&r.data_domain];if v.iter().any(|x|x.trim().is_empty()||x.chars().any(char::is_control)){return Err(HealthStateRepositoryError::AuthorizationDenied)}Ok(Self{principal_ref:r.principal_ref.clone(),subject_ref:r.subject_ref.clone(),scope:format!("{}:{}",r.tenant_id,r.data_domain),capability_id:r.capability_id.clone(),resource_type:r.resource_type.clone(),resource_id:r.resource_id.clone(),action:r.action.clone()})}pub fn principal_ref(&self)->&str{&self.principal_ref}pub fn subject_ref(&self)->&str{&self.subject_ref}pub fn scope(&self)->&str{&self.scope}pub fn capability_id(&self)->&str{&self.capability_id}pub fn resource_type(&self)->&str{&self.resource_type}pub fn resource_id(&self)->&str{&self.resource_id}pub fn action(&self)->&str{&self.action}}
#[derive(Debug,Clone,Default,PartialEq,Eq)]pub struct HealthStateQuery{pub entity_type:Option<String>,pub classification:Option<String>,pub content_type:Option<String>}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct HealthStateTimelineEntry{pub record_id:String,pub subject_ref:String,pub effective_time:Option<String>,pub recorded_at:String}
#[derive(Debug,Error,PartialEq,Eq)]pub enum HealthStateRepositoryError{#[error("authorization denied")]AuthorizationDenied,#[error("health state not found")]NotFound,#[error("health state is tombstoned")]Tombstoned,#[error("repository integrity failure")]IntegrityFailure,#[error("repository storage failure")]StorageFailure,#[error("invalid Health State entity")]InvalidEntity}
impl From<StorageError> for HealthStateRepositoryError{fn from(e:StorageError)->Self{match e{StorageError::AuthorizationDenied=>Self::AuthorizationDenied,StorageError::NotFound=>Self::NotFound,StorageError::Tombstoned=>Self::Tombstoned,StorageError::IndexIntegrityFailure|StorageError::RecordIntegrityFailure=>Self::IntegrityFailure,StorageError::InvalidRecord|StorageError::KeyResolutionFailed|StorageError::Io|StorageError::Serialization|StorageError::NonceGenerationFailed=>Self::StorageFailure}}}
pub trait HealthStateRepository{fn put(&self,r:LocalHealthVaultRecord,c:&AuthorizedHealthStateAccessContext)->Result<(),HealthStateRepositoryError>;fn get(&self,id:&str,c:&AuthorizedHealthStateAccessContext)->Result<LocalHealthVaultRecord,HealthStateRepositoryError>;fn query(&self,c:&AuthorizedHealthStateAccessContext,q:&HealthStateQuery)->Result<Vec<LocalHealthVaultRecord>,HealthStateRepositoryError>;fn timeline(&self,c:&AuthorizedHealthStateAccessContext)->Result<Vec<HealthStateTimelineEntry>,HealthStateRepositoryError>;fn tombstone(&self,id:&str,c:&AuthorizedHealthStateAccessContext)->Result<(),HealthStateRepositoryError>;fn verify(&self,id:&str,c:&AuthorizedHealthStateAccessContext)->Result<(),HealthStateRepositoryError>;}
pub struct LocalHealthStateRepository<K,A>{vault:LocalFileVaultStore<K,A>}impl<K,A>LocalHealthStateRepository<K,A>where K:VaultKeyProvider,A:VaultAuthorizer{pub fn new(v:LocalFileVaultStore<K,A>)->Self{Self{vault:v}}fn vc(c:&AuthorizedHealthStateAccessContext)->AuthorizationContext{AuthorizationContext{principal_ref:c.principal_ref().to_owned(),subject_ref:c.subject_ref().to_owned(),scope:c.scope().to_owned()}}fn valid(r:&LocalHealthVaultRecord)->Result<(),HealthStateRepositoryError>{if !ALLOWED_ENTITY_TYPES.contains(&r.entity_type.as_str())||r.content_type!=HEALTH_STATE_CONTENT_TYPE||r.record_id.trim().is_empty()||r.subject_ref.trim().is_empty(){Err(HealthStateRepositoryError::InvalidEntity)}else{Ok(())}}}
impl<K,A>HealthStateRepository for LocalHealthStateRepository<K,A>where K:VaultKeyProvider,A:VaultAuthorizer{fn put(&self,r:LocalHealthVaultRecord,c:&AuthorizedHealthStateAccessContext)->Result<(),HealthStateRepositoryError>{Self::valid(&r)?;if r.subject_ref!=c.subject_ref(){return Err(HealthStateRepositoryError::AuthorizationDenied)}self.vault.put(r,&Self::vc(c)).map_err(Into::into)}fn get(&self,id:&str,c:&AuthorizedHealthStateAccessContext)->Result<LocalHealthVaultRecord,HealthStateRepositoryError>{let r=self.vault.get(id,&Self::vc(c)).map_err(HealthStateRepositoryError::from)?;Self::valid(&r)?;if r.subject_ref!=c.subject_ref(){return Err(HealthStateRepositoryError::AuthorizationDenied)}Ok(r)}fn query(&self,c:&AuthorizedHealthStateAccessContext,q:&HealthStateQuery)->Result<Vec<LocalHealthVaultRecord>,HealthStateRepositoryError>{let e=self.vault.list(&Self::vc(c)).map_err(HealthStateRepositoryError::from)?;let mut out=Vec::new();for x in e{if !ALLOWED_ENTITY_TYPES.contains(&x.entity_type.as_str())||q.entity_type.as_ref().is_some_and(|v|x.entity_type!=*v)||q.classification.as_ref().is_some_and(|v|x.classification!=*v)||q.content_type.as_ref().is_some_and(|v|x.content_type!=*v){continue}out.push(self.get(&x.record_id,c)?)}Ok(out)}fn timeline(&self,c:&AuthorizedHealthStateAccessContext)->Result<Vec<HealthStateTimelineEntry>,HealthStateRepositoryError>{let e=self.vault.list(&Self::vc(c)).map_err(HealthStateRepositoryError::from)?;let mut t=e.into_iter().filter(|x|ALLOWED_ENTITY_TYPES.contains(&x.entity_type.as_str())).map(|x|HealthStateTimelineEntry{record_id:x.record_id,subject_ref:x.subject_ref,effective_time:None,recorded_at:x.created_at}).collect::<Vec<_>>();t.sort_by(|l,r|match(&l.effective_time,&r.effective_time){(Some(a),Some(b))=>match a.cmp(b){Ordering::Equal=>l.recorded_at.cmp(&r.recorded_at),o=>o},(Some(_),None)=>Ordering::Less,(None,Some(_))=>Ordering::Greater,(None,None)=>l.recorded_at.cmp(&r.recorded_at)}.then_with(||l.record_id.cmp(&r.record_id)));Ok(t)}fn tombstone(&self,id:&str,c:&AuthorizedHealthStateAccessContext)->Result<(),HealthStateRepositoryError>{self.vault.tombstone(id,&Self::vc(c)).map_err(Into::into)}fn verify(&self,id:&str,c:&AuthorizedHealthStateAccessContext)->Result<(),HealthStateRepositoryError>{self.vault.verify(id,&Self::vc(c)).map_err(Into::into)}}
#[cfg(test)]mod tests{use super::*;#[test]fn delegated_context_preserves_actor_and_subject(){let r=AuthorizationRequest{principal_ref:"clinician-1".into(),subject_ref:"patient-1".into(),capability_id:"health.state.read".into(),resource_type:"health_state".into(),resource_id:"record-1".into(),action:"read".into(),tenant_id:"tenant-1".into(),data_domain:"personal_health".into()};let c=AuthorizedHealthStateAccessContext::from_authorized_request(&r).unwrap();assert_eq!(c.principal_ref(),"clinician-1");assert_eq!(c.subject_ref(),"patient-1");assert_ne!(c.principal_ref(),c.subject_ref())}}
